function parse(v) { try { return typeof v === "string" ? JSON.parse(v) : v; } catch (_) { return null; } }
function isStatusQuestion(value) {
  const text = String(value || "").toLowerCase().replace(/\s+/g, " ").trim();
  if (/\b(status|update|progress|eta)\b/.test(text)) return true;
  if (/\b(when|what time|how soon)\b.{0,100}\b(arrive|coming|help|someone|fixed|fix|resolved|resolve|completed|complete|done|repair|repairs|issue|issues|request|requests)\b/.test(text)) return true;
  if (/\b(arrive|coming|fixed|resolved|completed|done)\b.{0,60}\b(when|what time|how soon)\b/.test(text)) return true;
  return /\bwhat(?:'s| is) happening with\b.{0,60}\b(issue|issues|request|requests|repair|repairs)\b/.test(text);
}
function hasConcreteMaintenanceDetail(value) {
  const text = String(value || "").toLowerCase();
  return /\b(leak|leaking|drip|dripping|water|wet|flood|gas|smoke|fire|burning|spark|wire|breaker|heat|cooling|air conditioning|fan|faucet|tap|sink|drain|shower|bath(?:tub)?|pipe|window|door|lock|hinge|toilet|pest|mold|crack|cracked|broken|stopped|not working|won'?t work|clog|overflow|sewage|noise|noisy|squeak|squeaky)\b/.test(text);
}
return $input.all().map((item) => {
  const j = item.json;
  const ticket = parse(j.ticket);
  const openTickets = parse(j.open_tickets) || [];
  const bufferedText = String(j.pending_intake_body || "").trim();
  const combinedTenantText = [bufferedText, j.text].filter(Boolean).join("\n");
  const status = isStatusQuestion(j.text);
  let route = "new";
  if (j.is_bare_start) route = "welcome";
  else if (j.is_new_command) route = "new_command";
  else if (status) route = "status";
  else if (ticket && Array.isArray(ticket.missing_info) && ticket.missing_info.length) route = "clarification";
  else if (!hasConcreteMaintenanceDetail(combinedTenantText)) route = "pretriage";
  return {json: {...j, ticket, open_tickets: openTickets, combined_tenant_text: combinedTenantText, route}};
});

