WITH input_values AS (SELECT $1::text AS chat_id, $2::text AS msg_id, NULLIF($3::text, '') AS tenant_email), ticket AS (
  SELECT * FROM triage.tickets WHERE msg_id = (SELECT msg_id FROM input_values) ORDER BY id DESC LIMIT 1
), upsert_chat AS (
  INSERT INTO triage.tenant_chats (telegram_chat_id, tenant_email, active_ticket_id) SELECT chat_id, tenant_email, id FROM input_values CROSS JOIN ticket
  ON CONFLICT (telegram_chat_id) DO UPDATE SET tenant_email = coalesce(EXCLUDED.tenant_email, triage.tenant_chats.tenant_email), active_ticket_id = EXCLUDED.active_ticket_id, pending_intake_body = NULL, pending_intake_started_at = NULL, updated_at = now() RETURNING *
), linked AS (UPDATE triage.tickets SET tenant_chat_id = (SELECT telegram_chat_id FROM upsert_chat) WHERE id = (SELECT id FROM ticket) RETURNING *)
INSERT INTO triage.ticket_messages (ticket_id, channel, direction, intent, body, external_message_id, delivery_state)
SELECT id, 'telegram', 'inbound', 'request', body_clean, msg_id, 'RECORDED' FROM linked
ON CONFLICT (channel, direction, external_message_id) DO NOTHING
RETURNING ticket_id, (SELECT ref FROM linked) AS ref, (SELECT priority FROM linked) AS priority, (SELECT issue_summary FROM linked) AS issue_summary, (SELECT missing_info FROM linked) AS missing_info, (SELECT human_only FROM linked) AS human_only, (SELECT vendor_status FROM linked) AS vendor_status, (SELECT tenant_chat_id FROM linked) AS chat_id;

